import {Expedition,SECTORS,dist} from './world.js';
import {Renderer} from './render.js';
import {AudioEngine} from './audio.js';
const $=id=>document.getElementById(id),hide=id=>$(id).classList.add('hidden'),show=id=>$(id).classList.remove('hidden');
const renderer=new Renderer($('ocean')),audio=new AudioEngine();
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{/* Private browsing may disable storage. */}};
let best=read('null-tide-best',0),game=new Expedition(271828),mode='title',previous=0,accumulator=0,hudTime=0,toastTimer=0,oldFocus=null;
let keys=new Set(),touch={x:0,y:0},holding=false,performanceFrames=0,performanceStart=0;
renderer.setWorld(game.map);renderer.reduced=read('null-tide-reduced',renderer.reduced);audio.enabled=read('null-tide-sound',true);updateSound();
if(best)$('best-title').textContent=`PERSONAL RECORD / ${best.toLocaleString()} DATA`;
function formatTime(seconds){const t=Math.max(0,Math.ceil(seconds));return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`;}
function clearInput(){keys.clear();touch={x:0,y:0};holding=false;$('joystick-knob').style.transform='';}
function notify(title,body='',duration=4){$('toast-title').textContent=title;$('toast-body').textContent=body;show('toast');toastTimer=duration;}
function openModal(html){oldFocus=document.activeElement;$('modal-content').innerHTML=html;show('modal');clearInput();requestAnimationFrame(()=>{$('modal-content').querySelector('button,a,input')?.focus();});}
function closeModal(){hide('modal');oldFocus?.focus?.({preventScroll:true});clearInput();}
function start(){audio.init();audio.play('sector');game=new Expedition(crypto.getRandomValues(new Uint32Array(1))[0]);renderer.setWorld(game.map);mode='playing';for(const id of ['title-screen','title-depth','title-footer'])hide(id);show('hud');show('pause');document.body.classList.add('playing');closeModal();updateHUD();notify('潜航開始 — 忘却の庭','SPACE で周囲を探知。黄の記録を回収し、中央へ帰還。',6);}
function input(){return{x:(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x,y:(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.y,interact:keys.has('KeyE')||holding};}
function pulse(){if(mode==='playing'){audio.init();if(game.pulse())updateHUD();}}
function dash(){if(mode==='playing'){const i=input();game.dash(i.x,i.y);}}
function pause(){if(mode!=='playing')return;mode='paused';openModal(`<div class="micro">SIGNAL ON HOLD</div><h2 id="modal-title">静かな海で、ひと休み。</h2><p>潜航を一時停止しています。<br>酸素も監視機も、再開するまで止まっています。</p><div class="modal-actions"><button class="primary" id="resume"><span>潜航を続ける<small>RESUME EXPEDITION</small></span><span class="button-arrow">↗</span></button><button class="secondary" id="pause-help">操作ガイド</button><button class="secondary" id="abandon">タイトルへ</button></div>`);$('resume').onclick=resume;$('pause-help').onclick=()=>help('paused');$('abandon').onclick=()=>{closeModal();toTitle();};}
function resume(){closeModal();mode='playing';}
function toTitle(){mode='title';game=new Expedition(271828);renderer.setWorld(game.map);show('title-screen');show('title-depth');show('title-footer');hide('hud');hide('pause');hide('toast');document.body.classList.remove('playing');$('best-title').textContent=best?`PERSONAL RECORD / ${best.toLocaleString()} DATA`:'';clearInput();}
function help(returnTo=mode){if(mode==='playing')mode='paused';openModal(`<div class="micro">FIELD MANUAL / 取扱説明</div><h2 id="modal-title">音で、闇を読む。</h2><p>各海域にある <b>3つの記録</b> を回収し、中央の帰還点へ。<br>全3海域を踏破して、沈んだ街の記憶を持ち帰ろう。</p><div class="controls-grid"><div class="control"><kbd>W A S D</kbd><kbd>↑ ← ↓ →</kbd> 移動<small>機体には慣性があります。狭い通路では早めに減速。</small></div><div class="control"><kbd>SPACE</kbd> ソナー<small>暗闇を一時的に照らします。音を聞いた監視機が接近。</small></div><div class="control"><kbd>SHIFT</kbd> 緊急加速<small>加速中は無敵。接触した監視機を一時停止させます。</small></div><div class="control"><kbd>E</kbd> 長押しで回収・帰還<small>黄の記録に接近して回収。全回収後、中央の□へ。</small></div><div class="control"><kbd>ESC</kbd> 一時停止<small>スマホは左のスティックで移動、右のボタンで操作。</small></div><div class="control">◇ 記憶のかけら / ▰ 酸素補給<small>かけらは得点と酸素+3秒。補給装置は酸素+36秒。</small></div></div><p>敵の接近は赤い光が目印。加速の再使用は2.4秒、ソナーは4.8秒。<br>海域を突破すると耐久と酸素が全回復し、機体を強化できます。</p><label class="quality-toggle"><input type="checkbox" id="reduce" ${renderer.reduced?'checked':''}> 画面の揺れ・環境の動きを抑える</label><div class="modal-actions"><button class="primary" id="close-help"><span>${returnTo==='title'?'海へ戻る':'潜航を続ける'}<small>RETURN TO THE DEEP</small></span><span class="button-arrow">↗</span></button></div>`);$('reduce').onchange=e=>{renderer.reduced=e.target.checked;save('null-tide-reduced',renderer.reduced);};$('close-help').onclick=()=>{closeModal();mode=returnTo==='title'?'title':'playing';};}
function credits(){openModal(`<div class="micro">FIELD NOTES / 制作ノート</div><h2 id="modal-title">小さな実験の、その先へ。</h2><p>NULL TIDE は、GitHub の小規模な実験作から着想を得た独自作品です。<br>コード、ピクセル描画、音楽・効果音は、このゲーム用に制作しています。</p><div class="source-links"><a href="https://github.com/NomanT17/Echo-Pulse" target="_blank" rel="noreferrer">01 / Echo Pulse ↗<small>消えていく情報を、ソナーで読み取るという遊び。</small></a><a href="https://github.com/js13kGames/fear-the-dark" target="_blank" rel="noreferrer">02 / Fear the Dark ↗<small>光と暗闇が作る、探索の緊張感。</small></a><a href="https://github.com/igamerx/DungeonOfCurse_JS13K_24" target="_blank" rel="noreferrer">03 / Dungeon of Curse ↗<small>時間の制約で、短い探索の密度を高める設計。</small></a><a href="https://github.com/tanuki276/knutKning" target="_blank" rel="noreferrer">SOURCE / tanuki276/knutKning ↗<small>依存ライブラリなし。Canvas 2D / Web Audio / ES Modules。</small></a></div><div class="modal-actions"><button class="secondary" id="close-credits">閉じる</button></div>`);$('close-credits').onclick=closeModal;}
const upgradeOptions=[{id:'engine',symbol:'»',name:'潮流エンジン',label:'PROPULSION / +18%',description:'最高移動速度が18%上昇。\n次の海域を、軽やかに進む。'},{id:'sonar',symbol:'◎',name:'広域受信アンテナ',label:'SONAR RANGE / +25%',description:'ソナーの探知範囲が25%拡大。\n遠くの記録も見通せる。'},{id:'oxygen',symbol:'∞',name:'循環式酸素タンク',label:'OXYGEN USE / −24%',description:'酸素の消費量を24%軽減。\nより深く、より長く潜る。'}];
function upgradeScreen(){mode='upgrade';const s=SECTORS[game.sector];openModal(`<div class="micro">SECTOR 0${game.sector+1} COMPLETE / 記録回収完了</div><h2 id="modal-title">${s.name}の記憶</h2><p class="lead">${s.log}</p><p>耐久・酸素を全回復。次の潜航に向け、強化をひとつ選んでください。</p><div class="upgrades">${upgradeOptions.map(u=>`<button class="upgrade" data-upgrade="${u.id}"><span>${u.symbol}</span><small>${u.label}</small><strong>${u.name}</strong><p>${u.description.replace('\n','<br>')}</p></button>`).join('')}</div><p class="micro">NEXT / ${SECTORS[game.sector+1].english} — ${SECTORS[game.sector+1].depth.toLocaleString()} m</p>`);for(const b of document.querySelectorAll('[data-upgrade]'))b.onclick=()=>{game.upgrade(b.dataset.upgrade);renderer.setWorld(game.map);closeModal();mode='playing';audio.play('sector');updateHUD();notify(`SECTOR 0${game.sector+1} — ${SECTORS[game.sector].name}`,'監視機の反応が増えています。ソナーと加速を使い分けて。',5);};}
function result(won,reason){mode=won?'won':'lost';const isBest=game.score>best;if(isBest){best=game.score;save('null-tide-best',best);}const rank=won?(game.hits===0?'S':game.hits<5?'A':'B'):'—';openModal(`<div class="micro">${won?'ALL ARCHIVES RECOVERED':'EXPEDITION LOST'} / ${won?'全記録、回収完了':'通信途絶'}</div><h2 id="modal-title">${won?'海は、あなたを覚えている。':'その信号は、海に溶けた。'}</h2><p class="lead">${won?SECTORS[2].log:reason+'。\n持ち帰れなかった記録が、まだ海底で待っています。'}</p><div class="result-stats"><div><span class="micro">TOTAL DATA</span><strong>${game.score.toLocaleString()}</strong></div><div><span class="micro">ARCHIVES</span><strong>${game.recovered} / 9</strong></div><div><span class="micro">TIME</span><strong>${formatTime(game.elapsed)}</strong></div><div><span class="micro">RANK</span><strong>${rank}</strong></div></div><p>${isBest?'PERSONAL BEST — 自己記録を更新しました。':`PERSONAL BEST / ${best.toLocaleString()} DATA`}<br>ソナー ${game.pings} 回 · 被弾 ${game.hits} 回</p><div class="modal-actions"><button class="primary" id="retry"><span>もう一度、深くへ<small>NEW EXPEDITION</small></span><span class="button-arrow">↘</span></button><button class="secondary" id="result-title">タイトルへ</button></div>`);$('retry').onclick=start;$('result-title').onclick=()=>{closeModal();toTitle();};}
function processEvents(){for(const e of game.events.splice(0)){audio.play(e.type);if(['shard','core','air','stun'].includes(e.type))renderer.burst(e.x,e.y,e.type==='core'?'#f7d5a0':'#9ed9c1',e.type==='core'?45:12);if(e.type==='core'){const count=game.map.cores.filter(c=>c.done).length;notify(count===3?'全記録の回収完了':'記録を回収しました',count===3?'中央の帰還点 □ で E を長押し。':'酸素 +15 秒 / 記録データ +500',4);}if(e.type==='air')notify('酸素供給装置に接続','酸素 +36 秒',2);if(e.type==='hit'){renderer.shake=12;notify('機体損傷 — 緊急加速で離脱','SHIFT / 加速中は監視機を停止できます',2.5);}if(e.type==='upgrade')upgradeScreen();if(e.type==='lost')result(false,e.reason);if(e.type==='won')result(true);}}
function updateHUD(){const p=game.player,sector=SECTORS[game.sector],n=game.map.cores.filter(c=>c.done).length;$('sector-label').textContent=`SECTOR 0${game.sector+1} / 03`;$('sector-name').textContent=sector.name;$('objective').innerHTML=n===3?'中央の帰還点へ <b>□ EXTRACTION</b>':`記録を回収する <b>${n} / 3</b>`;$('health').innerHTML=Array.from({length:game.maxHp},(_,i)=>`<i class="${i>=p.hp?'empty':''}"></i>`).join('');$('health').setAttribute('aria-label',`耐久 ${p.hp} / ${game.maxHp}`);$('score').textContent=game.score.toString().padStart(6,'0');$('oxygen-value').textContent=formatTime(p.oxygen);$('oxygen-bar').style.width=`${Math.max(0,p.oxygen/210*100)}%`;$('oxygen-value').closest('.oxygen').classList.toggle('low',p.oxygen<40);$('depth-label').textContent=`${sector.depth.toLocaleString()} m`;$('time').textContent=formatTime(game.elapsed);
  for(const [id,t,max] of [['pulse',p.pulse,4.8],['dash',p.dash,2.4]]){$(id).disabled=t>0;$(id+'-status').textContent=t>0?`${t.toFixed(1)}s`:'READY';$(id+'-fill').style.width=`${(1-t/max)*100}%`;}
  const near=game.near();if(near?.kind==='core'||(near?.kind==='exit'&&n===3)){show('interact');$('interact-label').textContent=near.kind==='core'?'長押しで記録を回収':'長押しで帰還する';$('interact-progress').style.width=`${(near.kind==='core'?near.target.progress:game.extraction/1.2)*100}%`;}else{hide('interact');holding=false;}
  let target=n===3?game.map.hub:game.map.cores.filter(c=>!c.done).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(target){let angle=Math.atan2(target.y-p.y,target.x-p.x);const arrow=['→','↘','↓','↙','←','↖','↑','↗'][(Math.round(angle/(Math.PI/4))+8)%8];$('waypoint').innerHTML=`<span>${arrow}</span> ${n===3?'帰還点':'記録信号'} / ${Math.round(dist(p,target)/6)} m`;}
  renderer.minimap($('minimap'),game);
}
function updateSound(){$('sound').innerHTML=`SOUND <span>${audio.enabled?'ON':'OFF'}</span>`;$('sound').setAttribute('aria-pressed',String(audio.enabled));}
$('start').onclick=start;$('pulse').onclick=pulse;$('dash').onclick=dash;$('pause').onclick=pause;$('help').onclick=()=>{if(['title','playing','paused'].includes(mode))help();};$('credits').onclick=credits;$('sound').onclick=()=>{audio.init();audio.toggle();updateSound();save('null-tide-sound',audio.enabled);};
$('map-toggle').onclick=()=>{const collapsed=$('minimap').classList.toggle('hidden');document.querySelector('.map-legend').classList.toggle('hidden',collapsed);$('map-toggle').setAttribute('aria-expanded',String(!collapsed));$('map-toggle').innerHTML=`BATHYMETRY <span>${collapsed?'+':'−'}</span>`;};
$('interact-button').addEventListener('pointerdown',e=>{if(mode!=='playing')return;e.preventDefault();holding=true;e.currentTarget.setPointerCapture(e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('interact-button').addEventListener(type,()=>holding=false);
let stickId=null,stickCenter=null;const stick=$('joystick');function moveStick(e){if(e.pointerId!==stickId)return;const dx=e.clientX-stickCenter.x,dy=e.clientY-stickCenter.y,d=Math.hypot(dx,dy),max=36;touch={x:d<5?0:dx/Math.max(max,d),y:d<5?0:dy/Math.max(max,d)};$('joystick-knob').style.transform=`translate(${touch.x*max}px,${touch.y*max}px)`;}
stick.addEventListener('pointerdown',e=>{if(mode!=='playing')return;e.preventDefault();stickId=e.pointerId;const r=stick.getBoundingClientRect();stickCenter={x:r.x+r.width/2,y:r.y+r.height/2};stick.setPointerCapture(e.pointerId);moveStick(e);});stick.addEventListener('pointermove',moveStick);for(const type of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(type,()=>{stickId=null;touch={x:0,y:0};$('joystick-knob').style.transform='';});
document.addEventListener('keydown',e=>{
  if(!$('modal').classList.contains('hidden')){if(e.code==='Tab'){const items=[...$('modal-content').querySelectorAll('button,a,input')];if(items.length){const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}}if(e.code==='Escape'){e.preventDefault();if(['paused','title'].includes(mode)){const close=$('close-help')||$('close-credits')||$('resume');close?.click();}}return;}
  if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyE'].includes(e.code))e.preventDefault();if(e.code==='Escape'){pause();return;}if(mode==='title'&&e.code==='Enter'){start();return;}if(mode!=='playing')return;keys.add(e.code);if(e.repeat)return;if(e.code==='Space')pulse();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();
});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(mode==='playing')pause();}});window.addEventListener('resize',()=>renderer.resize());
function frame(ms){const dt=Math.min(.05,(ms-previous)/1000||0);previous=ms;performanceFrames++;if(ms-performanceStart>1000){$('ocean').dataset.fps=String(Math.round(performanceFrames*1000/(ms-performanceStart)));performanceFrames=0;performanceStart=ms;}if(mode==='playing'){accumulator+=dt;while(accumulator>=1/60){game.tick(1/60,input());accumulator-=1/60;}processEvents();hudTime+=dt;if(hudTime>.08){updateHUD();hudTime=0;}}else accumulator=0;
  if(mode==='title'){game.player.angle=-.34+Math.sin(ms*.0002)*.12;game.pulses=game.pulses.filter(p=>p.age<4);for(const p of game.pulses){p.r+=dt*110;p.age+=dt;}if(game.pulses.length===0)game.pulses.push({x:game.player.x,y:game.player.y,r:0,age:0,max:450});}
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)hide('toast');}renderer.render(game,ms/1000,dt,mode==='title');requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
